INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('copd-jugendliche-umfrage-hlw-reutte-oegp-kongress','COPD bei Jugendlichen: 80 Prozent kennen die Lungenkrankheit nicht','Acht von zehn befragten Jugendlichen haben noch nie von COPD gehört. Eine Umfrage von Schülerinnen der HLW Reutte wurde beim Kongress der Lungenfachärzte präsentiert.','Die Lungenkrankheit COPD ist bei Jugendlichen in Österreich kaum bekannt. Das zeigt eine Umfrage, die vier Schülerinnen der HLW Reutte in Tirol im Rahmen ihrer Diplomarbeit durchgeführt haben. Acht von zehn befragten jungen Menschen hatten den Begriff noch nie gehört. Die Ergebnisse wurden als wissenschaftliches Poster beim Kongress der Österreichischen Gesellschaft für Pneumologie (ÖGP) gezeigt – laut der Fachgesellschaft war das das erste Mal, dass eine Schülerinnenarbeit dort vertreten war.

## COPD bei Jugendlichen: Die wichtigsten Ergebnisse

Für die Arbeit wurde eine Online-Befragung durchgeführt. Daran nahmen 244 Schülerinnen und Schüler im Alter zwischen 14 und 20 Jahren teil. Im Mittelpunkt stand die Frage, wie gut junge Menschen über die chronische Lungenerkrankung und ihre Ursachen Bescheid wissen.

- **80 Prozent** der Befragten kannten COPD nicht.
- **73 Prozent** stufen Rauchen und Vapen als schädlich für die Lunge ein.
- **64 Prozent** fühlen sich über die gesundheitlichen Folgen von Zigaretten und E-Zigaretten nicht oder nur teilweise ausreichend informiert.
- **84 Prozent** wünschen sich mehr Aufklärung zu diesen Themen im Unterricht.

Auffällig ist damit die Lücke zwischen einem allgemeinen Risikobewusstsein und konkretem Wissen: Die meisten Jugendlichen halten Rauchen für schädlich, die Krankheit, die daraus entstehen kann, ist ihnen aber weitgehend fremd.

## Was ist COPD?

COPD steht für „chronic obstructive pulmonary disease“, auf Deutsch chronisch obstruktive Lungenerkrankung. Es handelt sich um eine häufige, dauerhafte Erkrankung der Lunge, bei der die Atemwege verengt sind. Die ÖGP betont in ihrer Aussendung, dass COPD nicht heilbar ist. Als wichtigster Risikofaktor gilt das Rauchen.

Weil sich die Krankheit meist schleichend über viele Jahre entwickelt, wird sie oft erst im Erwachsenenalter erkannt. Umso wichtiger ist aus Sicht der Lungenfachleute, dass junge Menschen früh wissen, welche langfristigen Folgen der Griff zur Zigarette oder zur E-Zigarette haben kann.

## Lungenfachärztin sieht Schulen in der Pflicht

ÖGP-Vizepräsidentin Judith Löffler-Ragg, Leiterin der Abteilung für Pneumologie am LKH Hochzirl-Natters und an der Medizinischen Universität Innsbruck tätig, sieht in den Ergebnissen einen klaren Auftrag. Aus ihrer Sicht zeigen die Zahlen, wie wichtig eine frühe Aufklärung über Rauchen, Vapen und Lungenerkrankungen ist. Schulen könnten bei der Vorbeugung und beim Aufbau von Gesundheitskompetenz eine zentrale Rolle übernehmen.

Der Wunsch der Jugendlichen selbst stützt diese Einschätzung: Mehr als vier von fünf Befragten wollen, dass Rauchen, Vapen und Lungengesundheit im Unterricht stärker behandelt werden.

## Prävention: Was Eltern und Lehrkräfte tun können

Die Studie der HLW Reutte ist keine repräsentative Erhebung für ganz Österreich, sie liefert aber einen deutlichen Hinweis auf Wissenslücken. Für Eltern und Lehrkräfte ergeben sich daraus einige praktische Ansatzpunkte:

1. Über COPD und andere Folgeerkrankungen des Rauchens offen sprechen – nicht nur über Lungenkrebs.
2. E-Zigaretten und Vapes nicht als harmlose Alternative darstellen, sondern ebenso kritisch thematisieren.
3. Gesundheitsthemen in Projekte und Diplomarbeiten einbinden, wie es in Reutte geschehen ist.
4. Bei Fragen zum Rauchstopp auf professionelle Unterstützung verweisen, etwa durch Ärztinnen und Ärzte oder Beratungsangebote.

Das Projekt zeigt auch, dass Schülerinnen und Schüler selbst einen Beitrag zur Gesundheitsforschung leisten können: Eine Diplomarbeit aus Tirol hat es auf einen Fachkongress der Lungenmedizin geschafft und dort eine Debatte über Aufklärung an Schulen angestoßen.','gesundheit','Medizin','tirol','news','Presseinfo Redaktion','/assets/img/artikel/copd-jugendliche-umfrage-hlw-reutte-oegp-kongress.webp','Österreichische Gesellschaft für Pneumologie (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261024_OTS0016/copd-bei-jugendlichen-weitgehend-unbekannt-erstmals-schuelerinnen-mit-poster-beim-oegp-kongress','published','2026-10-26T17:50:00.000Z','2026-10-26T17:45:59.969Z','COPD bei Jugendlichen: 80 % kennen Krankheit nicht','COPD bei Jugendlichen: Eine Schülerinnen-Umfrage aus Reutte zeigt große Wissenslücken. 84 % wollen mehr Aufklärung zu Rauchen und Vapen in der Schule.','COPD bei Jugendlichen','["COPD","COPD bei Jugendlichen","Lungenkrankheit","Rauchen Jugendliche","Vapen Lunge","ÖGP Kongress","HLW Reutte Umfrage","Aufklärung Rauchen Schule","chronische Lungenerkrankung"]','COPD bei Jugendlichen: Schülerinnen betrachten ein Lungenmodell im Klassenzimmer','Two teenage students seen from behind sitting in a bright Austrian school classroom in Tyrol, looking at a large anatomical model of human lungs on a desk, alpine mountains visible through the window, soft autumn daylight','[{"q":"Was ist COPD?","a":"COPD ist eine chronisch obstruktive Lungenerkrankung, bei der die Atemwege dauerhaft verengt sind. Sie ist nicht heilbar, wichtigster Risikofaktor ist das Rauchen."},{"q":"Wie viele Jugendliche kennen COPD?","a":"In der Umfrage der HLW Reutte unter 244 Jugendlichen von 14 bis 20 Jahren hatten 80 Prozent noch nie von COPD gehört."},{"q":"Was wünschen sich die Jugendlichen?","a":"84 Prozent der Befragten wollen mehr Aufklärung über Rauchen, Vapen und deren Folgen im Schulunterricht."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
